// Teacher credentials
const teacherPrivateKey = "6381bdfbab3f7a8ab6d6186eecb8b09635b2f49c1b3663adcff5c4dbe25e8d09";
const teacherAddress = "0xc39d22dC2d0A3Ca341CE8F69EFA563D113607688";
